function* g() {
  let i = 0;
  while (i < 3) {
    const got = yield i;
    i += got ?? 1;
  }
}
async function main(): Promise<void> {
  const it = g();
  const a = it.next();
  const b = it.next();
  const c = it.next();
  const d = it.next();
  console.log(a.value, a.done, b.value, b.done, c.value, c.done, d.done);
}
